def is_not_prime(n):  # define your python functions here with appropriate parameters and return statement as per requirement  
    if n <= 1 or (n % 2 == 0 and n > 2): 
        return True     # all numbers less than two are not prime, except for the number one. All even integers greater than three can't be primes because they have more factors otherthan ones themselves which makes them non-prime by definition of a Prime Number  
    else:                  # if n is divisible then it returns False (not Principal)  and otherwise True(Prime). This logic will work for all numbers.    
        return not any((n % i == 0 for i in range(3, int(n**0.5) + 1 ,2)))

