def is_undulating(n):
    str_num = str(abs(n))  # convert n to string and remove negative sign if any (optional)

    for i in range(len(str_num)-1):  
        if not ((int)(str_num[i]) < int((str_num)[i+1])):      # compare each digit with the next one 
            return False                                    # If it's greater, then n is undulating. Otherwise - no such condition met and function returns True by default (optional)  
    if len(set([int(x) for x in str_num])) == 1:     # check all digits are the same or not 
        return False                                    # If they're different, then n is undulating. Otherwise - no such condition met and function returns True by default (optional).  
    else :                                              # if none of above conditions meet , it means that number has repeating digit(s) so returning false .    
         return  False

def is_majority(arr, n, x):    
    count = 0  # Count occurrences of element 'x'.  

    for i in range (n):        
        if arr[i] == x:            
            count += 1         

    return True if count > n/2 else False

