def consecutive_duplicates(lst):    
    result = [] # Initialize an empty list for storing final output  

    prev = 0;     

    '''iterate through each element in given array'''       
    for i in range (len( lst)): 

          if ((i == 0) or (lst[i] != lst[prev])) : # If current item is not equal to previous one then append it into result list.  
              result.append(lst[i])   

        prev = i;     # Update the value of last processed element 

    return (result)      ;# Return final output array after removing consecutive duplicates from given input sequence .

def check_min_heap(arr):  
    n = len(arr) 

    # Indexes starting from which we need to perform traversals
    startIdx = n // 2 - 1

    for i in range(startIdx, -1 ,-1): 
        idx = 2*i + 1  

        if (idx < n and arr[i] > arr[idx]) : return False       # Check left child node. If it's greater than parent then not a min heap   

        idx = 2 * i + 2; 

        if(idx<n):  
            if(arr[i]>arr[idx]):     #Check right child node, same as above line but for the second condition. If it's greater than parent then not a min heap   
                return False      

    return True  # Return true only when all nodes satisfy this property ie., they are in correct order with respect to their children and parents (min-heap)
